-- Classic 1.60: Forever twins of vanilla player spells (same name, spell level and effects as exactly one VMaNGOS spell, a different spell id) take the
-- vanilla spell's cast time, cooldowns, duration, range, mana cost and effect values. Generated by tools/classic_spell_values/gen_spell_twins.py. Safe to run again.
CREATE TABLE IF NOT EXISTS `classic_spell_twin` (`spell_id` int unsigned NOT NULL, `vanilla_spell_id` int unsigned NOT NULL, `spell_name` varchar(100) NOT NULL DEFAULT '', PRIMARY KEY (`spell_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
DELETE FROM `classic_spell_twin`;
DELETE FROM `classic_spell_info` WHERE `spell_id` IN (SELECT `spell_id` FROM `classic_spell_twin`);
DELETE FROM `classic_spell_cost` WHERE `spell_id` IN (SELECT `spell_id` FROM `classic_spell_twin`);
DELETE FROM `classic_spell_value` WHERE `spell_id` IN (SELECT `spell_id` FROM `classic_spell_twin`);
SELECT w.`spell_id`, x.`effect_index`, x.`effect`, x.`apply_aura`, x.`base_points`, x.`die_sides`, x.`points_per_level`, x.`misc_value`, x.`points_per_combo`, x.`bonus_coeff`, x.`spell_name`
FROM `classic_spell_twin` w JOIN `classic_spell_value` x ON x.`spell_id` = w.`vanilla_spell_id`;
